\label{def:par}
  Let $G=\tuple{\vertices[G],\gEdges[G]}$ and $H=\tuple{\vertices[H],\gEdges[H]}$ be graphs. We define the \defn{par} of $G$ and $H$ to be their disjoint union and the \defn{tensor} to be their join, i.e.:
  \begin{eqnarray*}
    G\vlbin{\parr}H&=&\tuple{\vertices[G]\uplus\vertices[H],\gEdges[G]\uplus\gEdges[H]}\\
    G\vlbin{\otimes}H&=&\tuple{\vertices[G]\uplus\vertices[H],\gEdges[G]\uplus\gEdges[H]\uplus\set{vw\mid v\in\vertices[G],w\in\vertices[H]}}
  \end{eqnarray*}

\begin{eqnarray*}
    G\vlbin{\parr}H&=&\tuple{\vertices[G]\uplus\vertices[H],\gEdges[G]\uplus\gEdges[H]}\\
    G\vlbin{\otimes}H&=&\tuple{\vertices[G]\uplus\vertices[H],\gEdges[G]\uplus\gEdges[H]\uplus\set{vw\mid v\in\vertices[G],w\in\vertices[H]}}
  \end{eqnarray*}

\begin{equation}\label{eq:TensPar}
	\begin{array}{c@{\qquad\qquad\qquad\;}c}
		G\vlbin{\parr}H &G\vlbin{\otimes}H 
		\\
		\vgraph{1}{\begin{array}{cc}&\vm1 \\ G&\vdots \\ &\vm2 \end{array}}
		\qquad
		\vgraph{2}{\begin{array}{cc}\vm3 \\ \vdots&H \\ \vm4 \end{array}}
		&
		\vgraph{1}{\begin{array}{cc}&\vm1 \\ G&\vdots \\ &\vm2 \end{array}}
		\qquad
		\vgraph{2}{\begin{array}{cc}\vm3 \\ \vdots&H \\ \vm4 \end{array}}
		\joinedges{m1,m2}{m4,m3}
	\end{array}
\end{equation}

