Let us start with the following two inference rules
\begin{equation}\label{eq:id-ssu} 
  \vlinf{\mathsf{i}\mathord{\downarrow}}{}{\cneg A\vlbin{\parr}A}{\varnothing}
  \qquad\qquad
  \vlinf{\mathsf{s\mkern-1mu.\mkern-1mu sw}\mathord{\uparrow}}{~~S\subseteq\vertices[B],~S\neq\vertices[B]}{B\coons{A}S}{B\vlbin{\otimes}A}
\end{equation}
which are induced by the two Points~\ref{l:id} and~\ref{l:ssu}
above, and which are called \defn{identity down} and \defn{super switch up}, respectively.

\begin{equation}\label{eq:id-ssu} 
  \vlinf{\mathsf{i}\mathord{\downarrow}}{}{\cneg A\vlbin{\parr}A}{\varnothing}
  \qquad\qquad
  \vlinf{\mathsf{s\mkern-1mu.\mkern-1mu sw}\mathord{\uparrow}}{~~S\subseteq\vertices[B],~S\neq\vertices[B]}{B\coons{A}S}{B\vlbin{\otimes}A}
\end{equation}

\label{def:derivation}
  An \defn{inference system} $\mathsf{S}$ is a set of inference rules. We
  define the set of \defn{derivations} in $\mathsf{S}$ inductively below,
  and we denote a derivation $\mathcal{D}$ in $\mathsf{S}$ with premise $G$ and
  conclusion $H$, as follows:
  \begin{equation*}
    \od{\odd{\odh{G}}{\mathcal{D}}{H}{\mathsf{S}}}
  \end{equation*}
  \begin{enumerate}

  \item Every graph $G$ is a derivation (also denoted by $G$) with
    premise $G$ and conclusion $G$.


  \item   	
    If $G$ is a graph with $n$ vertices and
    $\mathcal{D}_1,\dots,\mathcal{D}_n$ are derivations with premise $G_i$ and conclusion
    $H_i$ for each $i\in\intset1n$,
    then $G\connn{\mathcal{D}_1,\dots, \mathcal{D}_n}$ is a derivation with
    premise $G\connn{G_1,\dots, G_n}$
    and conclusion $G\connn{H_1,\dots, H_n}$
    denoted as
    \begin{equation*}
    	\strut
    	\od{\odh{
    			G\Connn{
    				\od{\odd{\odh{G_1}}{\mathcal{D}_1}{H_1}{\mathsf{S}}}
	    			,\dots,
	    			\od{\odd{\odh{G_n}}{\mathcal{D}_n}{H_n}{\mathsf{S}}}}
    			}
    		}
    \end{equation*}
    respectively. If 
    $G=\vlbin{\parr}$ or $G=\vlbin{\otimes}$
    we may respectively write 
    \begin{equation*}
    	\strut\qquad
    	\od{\odh{\od{\odd{\odh{G_1}}{\mathcal{D}_1}{H_1}{\mathsf{S}}}
    			\vlbin{\parr}
    			\od{\odd{\odh{G_2}}{\mathcal{D}_2}{H_2}{\mathsf{S}}}}}
    	\qquad\mbox{or}\qquad
    	\od{\odh{\od{\odd{\odh{G_1}}{\mathcal{D}_1}{H_1}{\mathsf{S}}}
    			\vlbin{\otimes}
    			{\od{\odd{\odh{G_2}}{\mathcal{D}_2}{H_2}{\mathsf{S}}}}}}
    \end{equation*}


  \item If $\mathcal{D}_1$ is a derivation with premise $G_1$ and conclusion
    $H_1$, and $\mathcal{D}_2$ is a derivation with premise $G_2$ and
    conclusion $H_2$, and
    $$
    \vlinf{\mathsf{r}}{}{G_2}{H_1}
    $$ is an instance of an inference rule $\mathsf{r}$, then
    $\mathcal{D}_2\rcomp{\mathsf{r}}\mathcal{D}_1$ is a derivation with premise 
    {$G_1$} and
    conclusion $H_2$, denoted as
    \begin{equation*}
      \odn{
        \ods{G_1}{\mathcal{D}_1}{H_1}{\mathsf{S}}
      }{
        \mathsf{r}
      }{
        \ods{G_2}{\mathcal{D}_2}{H_2}{\mathsf{S}}
      }{}
      \qquad\mbox{or}\qquad
      \od{
        \odd{\odd{\odh{G_1}}{\mathcal{D}_1}{\odn{H_1}{\mathsf{r}}{G_2}{}
          }{\mathsf{S}}}{
              \mathcal{D}_2}{H_2}{\mathsf{S}}}
      \qquad\mbox{or}\qquad
      \od{\odd{\odi{\odd{\odh{G_1}}{
              \mathcal{D}_1}{H_1}{\mathsf{S}}}{
            \mathsf{r}}{G_2}{}}{
          \mathcal{D}_2}{H_2}{\mathsf{S}}}
    \end{equation*}
    If $H_1\isom[f]G_2$ we can compose $\mathcal{D}_1$ and $\mathcal{D}_2$ directly to
    $\mathcal{D}_2\mathop{\circ}\mathcal{D}_1$, denoted as
    \begin{equation}\label{eq:iso}
      \quad\;
      \od{\odo
        {\odh{\ods{G_1}{\mathcal{D}_1}{H_1}{\mathsf{S}}}}
        {f}
        {\ods{G_2}{\mathcal{D}_2}{H_2}{\mathsf{S}}}
        {}}
      \;\quad\mbox{or}\quad\;
      \od{\odo
        {\odh{\ods{G_1}{\mathcal{D}_1}{H_1}{\mathsf{S}}}}
        {\isom}
        {\ods{G_2}{\mathcal{D}_2}{H_2}{\mathsf{S}}}
        {}}
     \;\quad\mbox{or}\quad\;
      \od{\odo
        {\odh{\ods{G_1}{\mathcal{D}_1}{H_1}{\mathsf{S}}}}
        {}
        {\ods{G_2}{\mathcal{D}_2}{H_2}{\mathsf{S}}}
        {}}
     \;\quad\mbox{or}\quad\;
    \od{\odd{\odo{\odd{\odh{G_1}}{
    				\mathcal{D}_1}{H_1}{\mathsf{S}}}{
    			\mathsf{r}}{G_2}{}}{
    		\mathcal{D}_2}{H_2}{\mathsf{S}}}       
     \;\quad\mbox{or}\quad\;    	
    	      \od{
    		\odd{\odd{\odh{G_1}}{\mathcal{D}_1}{\od{\odo{\odh{H_1}}{\mathsf{r}}{G_2}{}}
    			}{\mathsf{S}}}{
    			\mathcal{D}_2}{H_2}{\mathsf{S}}}    
    \end{equation}
    If $f$ is clear from context we will simply write
    $\mathcal{D}_2\mathop{\circ}\mathcal{D}_1$ as
    \begin{equation}\label{eq:iso-}
      \hskip5em
      \od{\odd{\odd{\odh{G_1}}
          {\mathcal{D}_1}{H_1}{\mathsf{S}}}
        {\mathcal{D}_2}{H_2}{\mathsf{S}}}
      \qquad\mbox{or}\qquad
      \od{\odd{\odd{\odh{G_1}}
          {\mathcal{D}_1}{G_2}{\mathsf{S}}}
        {\mathcal{D}_2}{H_2}{\mathsf{S}}}
      \quad
    \end{equation}
    where we only write $H_1$ or $G_2$ in the middle, omitting the isomorphism step,
    in order to ease readability. However, even if $f$ is not written, we
      always assume it is part of the derivation and explicitely
      given.
  \end{enumerate}
  A \defn{proof} in $\mathsf{S}$ is a derivation in $\mathsf{S}$ whose premise
  is~$\varnothing$. A graph $G$ is \defn{provable} in $\mathsf{S}$ iff there is
  a proof in $\mathsf{S}$ with conclusion $G$. We denote this as
  $\proves[\mathsf{S}]{G}$ (or simply as $\proves{G}$ if $\mathsf{S}$ is
  clear from the context). The \defn{length} of a derivation $\mathcal{D}$, denoted
  by $\sizeof\mathcal{D}$, is the number of inference rule instances in $\mathcal{D}$.

\begin{equation*}
    \od{\odd{\odh{G}}{\mathcal{D}}{H}{\mathsf{S}}}
  \end{equation*}

