Let $\mathsf{S}$ be an inference system. We say that an inference rule
$\mathsf{r}$ is \defn{derivable} in $\mathsf{S}$ iff 
\begin{equation*}
  \mbox{for every instance}
  \hskip.5em
  \vlinf{\mathsf{r}}{}{H}{G}
  \quad
  \mbox{there is a derivation}
  \hskip.5em
  \smash{\od{\odd{\odh{G}}{\mathcal{D}}{H}{\mathsf{S}}}}
  \;\;.
\end{equation*}
We say that $\mathsf{r}$ is \defn{admissible} in $\mathsf{S}$ iff
\begin{equation*}
  \mbox{for every instance}
  \hskip.5em
  \vlinf{\mathsf{r}}{}{H}{G}
  \quad
  \mbox{we have that~~}
  \proves[\mathsf{S}]{G}
  \mbox{~~implies~~}
  \proves[\mathsf{S}]{H}
  \;\,.
\end{equation*}

\begin{equation*}
