\label{lem:g}
  Let $G$  and 
  $M_1,\dots,M_n, N_1, \dots, N_n$ be graphs with $\sizeof\vertices[G]=n$,
  such that for every $i\in\set{1,\ldots,n}$, 
  we have that $M_i=\varnothing$ implies $N_i=\varnothing$.
  Then there are derivations
  \begin{equation}\label{eq:gd}
    \ods{(M_1\vlbin{\parr}N_1)\vlbin{\otimes}\cdots\vlbin{\otimes}(M_n\vlbin{\parr}N_n)}
        {}{G\connn{M_1,\ldots,M_n}\vlbin{\parr}\cneg G\connn{N_1,\ldots,N_n}}{\mathsf{SGS}\mathord{\downarrow}}
  \end{equation}
  and dually
  \begin{equation}\label{eq:gu}
    \ods{G\connn{M_1,\ldots,M_n}\vlbin{\otimes}\cneg G\connn{N_1,\ldots,N_n}}
        {}{(M_1\vlbin{\otimes}N_1)\vlbin{\parr}\cdots\vlbin{\parr}(M_n\vlbin{\otimes}N_n)}{\mathsf{SGS}\mathord{\uparrow}}
  \end{equation}

\begin{equation}\label{eq:gd}
    \ods{(M_1\vlbin{\parr}N_1)\vlbin{\otimes}\cdots\vlbin{\otimes}(M_n\vlbin{\parr}N_n)}
        {}{G\connn{M_1,\ldots,M_n}\vlbin{\parr}\cneg G\connn{N_1,\ldots,N_n}}{\mathsf{SGS}\mathord{\downarrow}}
  \end{equation}

\begin{equation}\label{eq:gu}
    \ods{G\connn{M_1,\ldots,M_n}\vlbin{\otimes}\cneg G\connn{N_1,\ldots,N_n}}
        {}{(M_1\vlbin{\otimes}N_1)\vlbin{\parr}\cdots\vlbin{\parr}(M_n\vlbin{\otimes}N_n)}{\mathsf{SGS}\mathord{\uparrow}}
  \end{equation}

\sloppy
  For showing~\eqref{eq:gd}, we proceed by induction on $\sizeof\vertices[G]$.  First consider the
  case that there is an $i\in\set{1,\ldots,n}$ such that
  $N_i=\varnothing=M_i$. Without loss of generality, we can assume
  that $i=1$. Then there is a graph $H$ with $\sizeof\vertices[H]=n-1$ and
  $G\connn{M_1,\ldots,M_n}=H\connn{M_2,\ldots,M_n}$ and
  $\cneg G\connn{N_1,\ldots,N_n}=\cneg H\connn{N_2,\ldots,N_n}$,
  and therefore we have the derivation
  \begin{equation*}
    \mod{\odo{\odd{\odo{\odh{
            (\varnothing\vlbin{\parr}\varnothing)\vlbin{\otimes}(M_2\vlbin{\parr}N_2)\vlbin{\otimes}\cdots\vlbin{\otimes}(M_n\vlbin{\parr}N_n)}}{
          \isom}{(M_2\vlbin{\parr}N_2)\vlbin{\otimes}\cdots\vlbin{\otimes}(M_n\vlbin{\parr}N_n)}{}}{
          \mathcal{D}}{H\connn{M_2,\ldots,M_n}\vlbin{\parr}\cneg H\connn{N_2,\ldots,N_n}}{\mathsf{SGS}\mathord{\downarrow}}}{
        \isom}{G\connn{\varnothing,M_2,\ldots,M_n}\vlbin{\parr}\cneg G\connn{\varnothing,N_2,\ldots,N_n}}{}}
  \end{equation*}
  where $\mathcal{D}$ exists by induction hypothesis. We can therefore now
  assume that $M_i\neq\varnothing$ for all $i\in\set{1,\ldots,n}$. 
  We now make a case analysis on $G$ using Lemma~\ref{lem:newhope}:
  \begin{enumerate}[(i)]
  \item If $G$ is a singleton graph, the statement holds trivially.
  \item If $G=A\vlbin{\otimes}B$ then
    $G\connn{M_1,\ldots,M_n}=A\connn{M_1,\ldots,M_k}\vlbin{\otimes}B\connn{M_{k+1},\ldots,M_n}$
    and
    $\cneg G\connn{N_1,\ldots,N_n}=\cneg A\connn{N_1,\ldots,N_k}\vlbin{\parr}\cneg B\connn{N_{k+1},\ldots,N_n}$
    for some $1\le k\le n$. We therefore have
    \begin{equation*}
    \scalebox{.95}{$\strut\qquad
        \nvls{\odn{
          \ods{(M_1\vlbin{\parr}N_1)\vlbin{\otimes}\cdots\vlbin{\otimes}(M_k\vlbin{\parr}N_k)}
              {\mathcal{D}_1}{A\connn{M_1,\ldots,M_k}\vlbin{\parr}\cneg A\connn{N_1,\ldots,N_k}}{\mathsf{SGS}\mathord{\downarrow}}
              \vlbin{\otimes}
              \ods{(M_{k+1}\vlbin{\parr}N_{k+1})\vlbin{\otimes}\cdots\vlbin{\otimes}(M_n\vlbin{\parr}N_n)}
                  {\mathcal{D}_2}{B\connn{M_{k+1},\ldots,M_n}\vlbin{\parr}\cneg B\connn{N_{k+1},\ldots,N_n}}{\mathsf{SGS}\mathord{\downarrow}}
        }
            {\mathsf{s\mkern-1mu.\mkern-1mu sw}\mathord{\downarrow}}{
              \odn{(A\connn{M_1,\ldots,M_k}\vlbin{\parr}\cneg A\connn{N_1,\ldots,N_k})\vlbin{\otimes}B\connn{M_{k+1},\ldots,M_n}}{
                \mathsf{s\mkern-1mu.\mkern-1mu sw}\mathord{\downarrow}}{
                (A\connn{M_1,\ldots,M_k}\vlbin{\otimes}B\connn{M_{k+1},\ldots,M_n})\vlbin{\parr}\cneg A\connn{N_1,\ldots,N_k}}{}                
              \vlbin{\parr}\cneg B\connn{N_{k+1},\ldots,N_n}}{}
      }
    $}
   \end{equation*}
    where $\mathcal{D}_1$ and $\mathcal{D}_2$ exist by induction hypothesis. Note that it is possible that $\cneg A\connn{N_1,\ldots,N_k}=\varnothing$ or $\cneg B\connn{N_{k+1},\ldots,N_n}=\varnothing$ (or both). In that case one (or both) of the two instances of $\mathsf{s\mkern-1mu.\mkern-1mu sw}\mathord{\downarrow}$ is vacuous.
  \item If $G=A\vlbin{\parr}B$, we proceed similarly.
  \item If $G=P\connn{A_1,\ldots,A_k}$ for $P$ prime and
    $k=\sizeof{\vertices[P]}\ge 4$ and $A_l\neq\varnothing$ for each
    $l\in\set{1,\ldots,k}$, then we have that
    $G\connn{M_1,\ldots,M_n}=P\connn{A_1\connn{M_{11},\ldots,M_{1h_1}},\ldots,A_k\connn{M_{k1},\ldots,M_{kh_k}}}$
    where $\set{M_1,\ldots,M_n}=\mathcal M_1\cup\cdots\cup\mathcal M_k$ and
    $\mathcal M_l=\set{M_{l1},\ldots,M_{lh_l}}$ and
    $\mathcal M_l\cap\mathcal M_j=\varnothing$ for $l\neq j$. Similarly, we have
    $\cneg G\connn{N_1,\ldots,N_n}=\cneg P\connn{\cneg{A_1}\connn{N_{11},\ldots,N_{1h_1}},\ldots,\cneg{A_k}\connn{N_{k1},\ldots,N_{kh_k}}}$
    where $\set{N_1,\ldots,N_n}=\mathcal N_1\cup\cdots\cup\mathcal N_k$ and
    $\mathcal N_l=\set{N_{l1},\ldots,N_{lh_l}}$ and
    $\mathcal N_l\cap\mathcal N_j=\varnothing$ for $l\neq j$.  Since $M_i\neq\varnothing$ for all $i\in\set{1,\ldots,n}$, we also have that 
	{$A_l\connn{M_{l1},\ldots,M_{lh_l}}\neq\varnothing$ for each $l\in\set{1,\ldots,k}$}
	.
	Therefore, we have the following derivation
    \begin{equation*}
    \scalebox{.9}{$\strut\qquad

        \nvls{\odn{
          \ods{(M_{11}\vlbin{\parr}N_{11})\vlbin{\otimes}\cdots\vlbin{\otimes}(M_{1h_1}\vlbin{\parr}N_{1h_1})}
              {\mathcal{D}_1}{\cneg{A_1}\connn{M_{11},\ldots,M_{1h_1}}\vlbin{\parr}A_1\connn{N_{11},\ldots,N_{1h_1}}}{\mathsf{SGS}\mathord{\downarrow}}
              \vlbin{\otimes}
              \cdots
              \vlbin{\otimes}
              \ods{(M_{k1}\vlbin{\parr}N_{k1})\vlbin{\otimes}\cdots\vlbin{\otimes}(M_{kh_k}\vlbin{\parr}N_{kh_k})}
                  {\mathcal{D}_k}{\cneg{A_k}\connn{M_{k1},\ldots,M_{kh_k}}\vlbin{\parr}A_k\connn{N_{k1},\ldots,N_{kh_k}}}{\mathsf{SGS}\mathord{\downarrow}}
        }
            {\mathsf{p}\mathord{\downarrow}}{
              P\connn{A_1\connn{M_{11},\ldots,M_{1h_1}},\ldots,A_k\connn{M_{k1},\ldots,M_{kh_k}}}                
              \vlbin{\parr}
              \cneg P\connn{\cneg{A_1}\connn{N_{11},\ldots,N_{1h_1}},\ldots,\cneg{A_k}\connn{N_{k1},\ldots,N_{kh_k}}}
              }{}
        }
    $}
   \end{equation*}
    where $\mathcal{D}_1,\ldots,\mathcal{D}_k$ exist by induction hypothesis. 
