\label{lem:splitting:multitens}
	Let $G$ be a graph,  and $A_1,\dots, A_n$ be non-empty graphs.

	If $\proves[\mathsf{GS}]{G\vlbin{\parr} ({A_1\vlbin{\otimes} \cdots \vlbin{\otimes} A_n})}$, 
	then there is a context $C\coonso R$ and graphs $K_1$, \dots , $K_n$, 
	such that  
	there are derivations
	\begin{equation*}
		\ods{C\coons{{K_1\vlbin{\parr} \cdots\vlbin{\parr} K_n}}R}{\mathcal{D}_G}{G}{\mathsf{GS}}
		\;,\;
		\ods{\varnothing}{\mathcal{D}_i}{K_i\vlbin{\parr}A_i}{\mathsf{GS}}
		\quad\mbox{and}\quad
		\ods{\varnothing}{\mathcal{D}_C}{C}{\mathsf{GS}}
		\hskip-1em
	\end{equation*}
	for all $i\in\set{1,\ldots,n}$.

\begin{equation*}
		\ods{C\coons{{K_1\vlbin{\parr} \cdots\vlbin{\parr} K_n}}R}{\mathcal{D}_G}{G}{\mathsf{GS}}
		\;,\;
		\ods{\varnothing}{\mathcal{D}_i}{K_i\vlbin{\parr}A_i}{\mathsf{GS}}
		\quad\mbox{and}\quad
		\ods{\varnothing}{\mathcal{D}_C}{C}{\mathsf{GS}}
		\hskip-1em
	\end{equation*}

\begin{equation*}
			\scalebox{.95}{
				\odn{
					\ods{\varnothing}{\mathcal{D}''}{G''\vlbin{\parr} P\connn{M_1,\ldots,M_n}\coons{G'}{R_P}}{\mathsf{GS}}}
				{\mathsf{s\mkern-1mu.\mkern-1mu sw}\mathord{\downarrow}}
					{G''\vlbin{\parr}G'\vlbin{\parr}P\connn{M_1,\ldots,M_n}}{}
			}\hskip-3em
		\end{equation*}

\begin{equation*}
			\odn{\ods{\varnothing}{
					\mathcal{D}'}{
