  \label{def:mult-gen-con}
  A \emph{multiplicative generalised connective} is an
$n$-ary connective $\mathsf C$ which admits a \emph{linear} and
\emph{context-free} (introduction) rule in the sequent calculus, that
is, a rule of the form
\begin{equation}\label{eq:multRule}
\vlderivation{
\vliiin{}{}{\vdash\Gamma, \mathsf C(\phi_{\sigma(1)}, \dots, \phi_{\sigma(n)})}
	{\vlhy{\vdash\Gamma_1,\phi_{1},\dots,\phi_{k_1}}}
	{\vlhy{\cdots}}
	{\vlhy{\vdash\Gamma_k, \phi_{1+i_{k-1}}, \dots, \phi_{n}}}
}
\quad
\begin{array}{l}
	\mbox{with }
	\Gamma=\Gamma_1\uplus\cdots\uplus \Gamma_k
	\\
	\mbox{and }
	\sigma \mbox{ a permutation of }\intset1n
\end{array}
\end{equation}

\begin{equation}\label{eq:multRule}
\vlderivation{
\vliiin{}{}{\vdash\Gamma, \mathsf C(\phi_{\sigma(1)}, \dots, \phi_{\sigma(n)})}
	{\vlhy{\vdash\Gamma_1,\phi_{1},\dots,\phi_{k_1}}}
	{\vlhy{\cdots}}
	{\vlhy{\vdash\Gamma_k, \phi_{1+i_{k-1}}, \dots, \phi_{n}}}
}
\quad
\begin{array}{l}
	\mbox{with }
	\Gamma=\Gamma_1\uplus\cdots\uplus \Gamma_k
	\\
	\mbox{and }
	\sigma \mbox{ a permutation of }\intset1n
\end{array}
\end{equation}

