						\odn{C''\coons{K''_A\vlbin{\parr}K'_A\vlbin{\parr}K_B}{R''}}{
							\mathsf{s\mkern-1mu.\mkern-1mu sw}\mathord{\downarrow}}{K''_A\vlbin{\parr}
							\ods{C''\coons{K'_A\vlbin{\parr}K_B}{R''}}{\mathcal{D}'_{G}}{K_Y\vlbin{\parr}G'}{}}{}}{R'}}{
					\mathsf{s\mkern-1mu.\mkern-1mu sw}\mathord{\downarrow}}{
					\ods{C'\coons{K''_A\vlbin{\parr}K_Y}{R'}}{\mathcal{D}''_{G}}{G''}{}\vlbin{\parr} G'}{}
				\quad\mbox{and}\quad
				\odn{
					\ods{\varnothing}{\mathcal{D}_{A}''}{K''_A\vlbin{\parr}\left(A''\vlbin{\otimes}
						\ods{\varnothing}{\mathcal{D}_{A'}}{K_{A'}\vlbin{\parr}A'}{}
						\right)}{}}{
					\mathsf{s\mkern-1mu.\mkern-1mu sw}\mathord{\downarrow}}{
					K''_A\vlbin{\parr}K'_A\vlbin{\parr}(A''\vlbin{\otimes}A')}{}
				\;.
				\hskip-7em
			\end{equation*}








			\item\label{split:b.III}

			This is the most involved sub-case of the proof, induced when the movement of $G'$ via the $\mathsf{s\mkern-1mu.\mkern-1mu sw}\mathord{\downarrow}$ rule results in a larger prime graph, where the $G'$ does not overlap with any existing module and possibly adds edges that break up some existing modules of $P$ into smaller modules in the resulting prime graph.  
			Assume  $\mathcal{D}$ is of shape

			\begin{equation*}
				\scalebox{.95}{
					\odn{\ods{\varnothing}{
							\mathcal{D}'}{
							G''\vlbin{\parr}Q\connn{G',N_2,\ldots,N_{k}}}{\mathsf{GS}}}{
						\mathsf{s\mkern-1mu.\mkern-1mu sw}\mathord{\downarrow}}{
						G''\vlbin{\parr}G'\vlbin{\parr}P\connn{M_1,\ldots,M_n}}{}
				}\hskip-3em
			\end{equation*}
			for a unique prime graph $Q$ (up to permutation of modules) such that $k=\sizeof\vertices[Q] > \sizeof{\vertices[P]}$ (hence $k \geq 4$) 
			such that
			\begin{equation}\label{eq:ross2}
				Q\connn{\varnothing,N_2,\ldots,N_{k}} \isom P\connn{M_1,\ldots,M_n}
			\end{equation}
			where for each $i \in \set{2, \ldots k}$ we have that $N_i \neq \varnothing$ and $N_i$ is a module of some $M_j$ where $j \in \set{1, \ldots n}$.
			We apply the induction hypothesis to $G''\vlbin{\parr}Q\connn{G',N_2,\ldots,N_{k}}$ 
			and get one of the following three sub-cases:



			\begin{enumerate}[(b.{III}.A), wide=0pt]
				\item \label{split:b.III.A}
				there is a context $C'\coonso{R' }$ and $K'_1, \dots, K'_k$ such that there are derivations
				\begin{equation*}
					\ods{C'\coons{\cneg Q\connn{K_1', \dots,  K'_k}}{R'}}{\mathcal{D}_G''}{G''}{\mathsf{GS}}
					\;,\;
					\ods{\varnothing}{\mathcal{D}_1'}{K'_1\vlbin{\parr} G'}{\mathsf{GS}}
					\;,\;
					\ods{\varnothing}{\mathcal{D}_i'}{K'_i\vlbin{\parr} N_i}{\mathsf{GS}}
					\quad\mbox{and}\quad
					\ods{\varnothing}{\mathcal{D}_C'}{C'}{\mathsf{GS}}
					\hskip-1em
				\end{equation*}
				for all $i\in\intset2k$.
				Since the graphs $N_2, \dots, N_n$  are non-empty by hypothesis, we can apply Lemma~\ref{lem:g} and obtain a derivation
				\begin{equation*}
					\ods{
						\left(
						\ods{\varnothing}{\mathcal{D}'_2}{K'_2\vlbin{\parr}N_2}{}
						\vlbin{\otimes}\cdots \vlbin{\otimes}
						\ods{\varnothing}{\mathcal{D}'_k}{K'_k\vlbin{\parr}N_k}{}
						\right)
					}{}{
						\cneg{Q} \connn{\varnothing, K'_2, \dots, K'_k}
						\vlbin{\parr} 
						Q\connn{\varnothing,N_2,\ldots,N_{k}} 
					}{\mbox{\small Lemma \ref{lem:g}}}
				\end{equation*}	
				By (\ref{eq:ross2}), 
				such a derivation is a derivation of 
				$\cneg Q\connn{\varnothing,K_2,\ldots,K_{k}} \vlbin{\parr}  P\connn{M_1,\ldots,M_n}$
				on which we can now apply the inductive hypothesis.
				This gives the two following cases

				\begin{itemize}
					\item 

					either there is a context $C''\coonso{R''}$ and graphs $K_1, \dots, K_k $ such that there are derivations	
					\begin{equation*}
						\ods{C''\coons{\cneg P\connn{K_1, \dots, K_k}}{R''}}{\mathcal{D}_Q}{\cneg{Q} \connn{\varnothing, K'_2, \dots, K'_k}}{\mathsf{GS}}
						\;,\;
						\ods{\varnothing}{\mathcal{D}_i}{K_i\vlbin{\parr} M_i}{\mathsf{GS}}
						\quad\mbox{and}\quad
						\ods{\varnothing}{\mathcal{D}_C''}{C''}{\mathsf{GS}}

					\end{equation*}
					for all $i \in\intset1n$. Then we conclude by letting $C\coonso{R}=C'\coons{C''\coonso{R''}}{R'}$ and $\mathcal{D}_G$ be the derivation
					\begin{equation*}
						\odn{
							C'\Coons{	\ods{C''\coons{\cneg P\connn{K_1, \dots, K_k}}{R''}}{\mathcal{D}_Q}{
									\cneg{Q} \Connn{\ods{\varnothing}{\mathcal{D}_1'}{K'_1\vlbin{\parr} G'}{}, K'_2, \dots, K'_k}
								}{}}{R'}
						}{\mathsf{s\mkern-1mu.\mkern-1mu sw}\mathord{\downarrow}}{
							\ods{C'\coons{\cneg Q\connn{K_1', \dots,  K'_k}}{R'}}{\mathcal{D}_G''}{G''}{}
							\vlbin{\parr} G'}{}
					\end{equation*}

					\item 
					or  there is a context $C''\coonso{R''}$ and graphs $K_X$ and $ K_Y $ such that, w.l.o.g. there are derivations	
					\begin{equation*}
						\ods{C''\coons{K_X \vlbin{\parr} K_Y }{R''}}{\mathcal{D}_Q}{\cneg{Q} \connn{\varnothing, K'_2, \dots, K'_k}}{\mathsf{GS}}
						\;,\;
						\ods{\varnothing}{\mathcal{D}_X}{K_X\vlbin{\parr} M_1}{\mathsf{GS}}
						\;,\;
						\ods{\varnothing}{\mathcal{D}_Y}{K_Y\vlbin{\parr} P \connn{\varnothing, M_2, \dots, M_n}}{\mathsf{GS}}
						\quad\mbox{and}\quad
						\ods{\varnothing}{\mathcal{D}_C''}{C''}{\mathsf{GS}}
						\hskip-6em
					\end{equation*}
					for an $i \in\intset1n$. 
					Then we conclude by letting $C\coonso{R}=C'\coonso{R'}$ and $\mathcal{D}_G$ be the derivation
					\begin{equation*}
						\odn{
							C'\Coons{
								\ods{C''\Coons{K_X \vlbin{\parr} K_Y }{R''}}{\mathcal{D}_Q}{
									\cneg{Q} \Connn{\ods{\varnothing}{\mathcal{D}_1'}{K'_1\vlbin{\parr} G'}{}, K'_2, \dots, K'_k}}{}
							}{R'}
						}{\mathsf{s\mkern-1mu.\mkern-1mu sw}\mathord{\downarrow}}{
							\ods{C'\coons{K'\vlbin{\parr} K_2 \vlbin{\parr}  \cdots\vlbin{\parr} K_n}{R'}}{\mathcal{D}_G''}{G''}{}
							\vlbin{\parr} G'}{}
					\end{equation*}

				\end{itemize}






				\item 
				there is a context $C'\coonso{R' }$ and $K'_X$ and $K'_Y$ such that (after \ref{eq:ross2}) there are derivations
				\begin{equation*}
					\ods{C'\coons{{K_X'\vlbin{\parr}  K'_Y}}R}{\mathcal{D}_G''}{G''}{\mathsf{GS}}
					\;,\;
					\ods{\varnothing}{\mathcal{D}_X'}{K'_X\vlbin{\parr} G'}{\mathsf{GS}}
					\;,\;
					\ods{\varnothing}{\mathcal{D}_Y'}{K'_Y\vlbin{\parr} P\connn{M_1, \dots, M_n}}{\mathsf{GS}}
					\quad\mbox{and}\quad
					\ods{\varnothing}{\mathcal{D}_C'}{C'}{\mathsf{GS}}
					\hskip-6em
				\end{equation*}
				We can now apply inductive hypothesis on $K'_Y\vlbin{\parr} P\connn{M_1, \dots, M_n}$ and we have the two following cases:
				\begin{itemize}
					\item there is a context $C''\coonso{R''}$ and graphs $K_1, \dots, K_n$ such that there are derivations
					\begin{equation*}
						\ods{C''\coons{\cneg P\connn{K_1, \dots, K_n}}{R''}}{\mathcal{D}_K}{K_Y'}{\mathsf{GS}}
						\;,\;
						\ods{\varnothing}{\mathcal{D}_i}{K_i\vlbin{\parr} M_i}{\mathsf{GS}}
						\quad\mbox{and}\quad
						\ods{\varnothing}{\mathcal{D}_C''}{C''}{\mathsf{GS}}
						\hskip-1em
					\end{equation*}
					In this case we can conclude similarly to the first case of \ref{split:b.III.A}, that is, 
					by letting $C\coonso{R}=C'\coons{C''\coonso{R''}}{R'}$ 
					and $\mathcal{D}_G$ be the derivation
					\begin{equation*}
						\odn{
							C'\Coons{	\ods{C''\coons{\cneg P\connn{K_1, \dots, K_n}}{R''}}{\mathcal{D}_K}{K_Y'}{}
								\vlbin{\parr} 					
								\ods{\varnothing}{\mathcal{D}_X'}{K'_X\vlbin{\parr} G'}{}
							}{R'} 
						}{\mathsf{s\mkern-1mu.\mkern-1mu sw}\mathord{\downarrow}}{
							\ods{C'\coons{K_X' \vlbin{\parr} K_Y'}{R'}}{\mathcal{D}_G''}{G''}{}
							\vlbin{\parr} G'}{}
					\end{equation*}

					\item
					or  there is a context $C''\coonso{R''}$ and graphs $K_X$ and $ K_Y $ such that, w.l.o.g. there are derivations	
					\begin{equation*}
						\ods{C''\coons{K_X \vlbin{\parr} K_Y }{R''}}{\mathcal{D}_K}{K_Y'}{\mathsf{GS}}
						\;,\;
						\ods{\varnothing}{\mathcal{D}_X}{K_X\vlbin{\parr} M_1}{\mathsf{GS}}
						\;,\;
						\ods{\varnothing}{\mathcal{D}_Y}{K_Y\vlbin{\parr} P \connn{\varnothing, M_2, \dots, M_n}}{\mathsf{GS}}
						\quad\mbox{and}\quad
						\ods{\varnothing}{\mathcal{D}_C''}{C''}{\mathsf{GS}}
						\hskip-6em
					\end{equation*}
					we conclude	by letting $C\coonso{R}=C'\coons{C''\coonso{R''}}{R'}$  and $\mathcal{D}_G$ be the derivation
					\begin{equation*}
						\odn{
							C'\Coons{	\ods{C''\coons{K_X\vlbin{\parr} K_Y}{R''}}{\mathcal{D}_K}{K_Y'}{}
								\vlbin{\parr} 					
								\ods{\varnothing}{\mathcal{D}_X'}{K'_X\vlbin{\parr} G'}{}
							}{R'} 
						}{\mathsf{s\mkern-1mu.\mkern-1mu sw}\mathord{\downarrow}}{
							\ods{C'\coons{K_X' \vlbin{\parr} K_Y'}{R'}}{\mathcal{D}_G''}{G''}{}
							\vlbin{\parr} G'}{}
					\end{equation*}	

				\end{itemize}





				\item 
				There is a context  $C'\coonso{R'}$ and there are graphs $ K_X' $ and $ K_Y'$ such that for have the following derivations for some $\ell \in \set{2, \dots k}$.
				\begin{equation*}
					\small
					\ods{C'\coons{ K_X' \vlbin{\parr} K_Y'}{R'}}{\mathcal{D}''_{G}}{G''}{\mathsf{GS}}
					\;,\;
					\ods{\varnothing}{\mathcal{D}_X'}{K_X' \vlbin{\parr} N_\ell}{\mathsf{GS}}
					\;,\;
					\ods{\varnothing}{\mathcal{D}_Y'}{K_Y' \vlbin{\parr} Q\connn{G', N_2, \ldots, N_{\ell-1}, \varnothing, N_{\ell+1}, \ldots N_k }}{\mathsf{GS}}
					\quad\mbox{and}\quad
					\ods{\varnothing}{\mathcal{D}_C'}{C'}{\mathsf{GS}}
                                        \hskip-4em
				\end{equation*}
				There are two cases to consider: either $N_\ell = M_m$ for some $m \in \intset1k$ or we have $M_m = M'\coons{N_\ell}{R_m}$ for some non-empty $M'$.

				We consider first the former case where $N_\ell = M_m$ for some $m \in \intset1k$,
				the derivation $\mathcal{D}_Y$ is defined, recalling that by~(\ref{eq:ross2}) we have $Q\connn{\varnothing,N_2,\ldots,N_{k}} \isom P\connn{M_1,\ldots,M_n}$
				and hence\\ $Q\connn{\varnothing, N_2, \ldots, N_{\ell-1}, \varnothing, N_{\ell+1}, \ldots N_k } \isom P\connn{M_1, \ldots, M_{m-1}, \varnothing, M_{m+1}, \ldots M_n }$, i.e.,
				\begin{equation*}
					\vlnostructuressyntax
					\odn{
						\ods{
							\varnothing
						}{\mathcal{D}_Y'}{
							K_Y' \vlbin{\parr} Q\connn{G', N_2, \ldots, N_{\ell-1}, \varnothing, N_{\ell+1}, \ldots N_k }
						}{}
					}{\mathsf{s\mkern-1mu.\mkern-1mu sw}\mathord{\downarrow}}{
						K_Y' \vlbin{\parr} G' \vlbin{\parr} P\connn{M_1, \ldots, M_{m-1}, \varnothing, M_{m+1}, \ldots M_n }
					}{}
				\end{equation*}
				We can conclude almost immediately by letting $C\coonso{R} = C'\coonso{R'}$, $K_Y = K_Y' \vlbin{\parr} G'$, $K_X = K_X'$, $\mathcal{D}_X = \mathcal{D}_X'$, $\mathcal{D}_Y = \mathcal{D}_Y'$, and $\mathcal{D}_G$ be the following derivation.
				\begin{equation*}
					\odn{
						C'\coons{
							K_Y \vlbin{\parr} K_X
						}{R'} 
					}{\mathsf{s\mkern-1mu.\mkern-1mu sw}\mathord{\downarrow}}{
						\ods{C'\coons{K_X' \vlbin{\parr} K_Y'}{R'}}{\mathcal{D}_G''}{G''}{}
						\vlbin{\parr} G'}{}
					\quad .
				\end{equation*}



				Otherwise, 
				we pursue the case where $M_m = M'\coons{N_\ell}{R_m}$ for some non-empty $M'$, which is more involved than the case above.
				By (\ref{eq:ross2}) we have 
				\begin{equation*}
					Q\connn{\varnothing, N_2, \ldots, N_{\ell-1}, \varnothing, N_{\ell+1}, \ldots N_k } 
					\isom
					P\connn{M_1, \ldots, M_{m-1}, M', M_{m+1}, \ldots M_n }
                                        \hskip-6em
				\end{equation*}
				Hence, we have a proof of $K_Y' \vlbin{\parr} G' \vlbin{\parr} P\connn{M_1, \ldots, M_{m-1}, M', M_{m+1}, \ldots M_n }$ obtained by applying the rule $\mathsf{s\mkern-1mu.\mkern-1mu sw}\mathord{\downarrow}$ to the conclusion of $\mathcal{D}_Y'$ above, as follows.
				\begin{equation*}
					\vlnostructuressyntax
					\odn{
						\ods{
							\varnothing
						}{\mathcal{D}_Y'}{
							K_Y' \vlbin{\parr} Q\connn{G', N_2, \ldots, N_{\ell-1}, \varnothing, N_{\ell+1}, \ldots N_k }
						}{}
					}{\mathsf{s\mkern-1mu.\mkern-1mu sw}\mathord{\downarrow}}{
						K_Y' \vlbin{\parr} G' \vlbin{\parr} P\connn{M_1, \ldots, M_{m-1}, M', M_{m+1}, \ldots M_n }
					}{}
				\end{equation*}


				By Observation \ref{obs:size} $\gsize{K_Y' \vlbin{\parr} G'} \leq \gsize{G}$ and also $N_\ell \neq \varnothing$, hence we have the following inequality.
				\[
				\gsize{K_Y' \vlbin{\parr} G' \vlbin{\parr} P\connn{M_1, \ldots, M_{m-1}, M', M_{m+1}, \ldots M_n }} < \gsize{ G \vlbin{\parr} P\connn{M_1, \ldots, M_{n} } }
                                \hskip-6em
				\]
				Therefore,  we can apply the induction hypothesis to the above mentioned proof of $K_Y\vlbin{\parr}G' \vlbin{\parr} P\connn{M_1, \ldots, M_{m-1}, M', M_{m+1}, \ldots M_n }$
				to obtain one of the following three sub-cases:


				\begin{enumerate}[(b.{III}.{C}.A), wide=0pt]

					\item\label{split:b:II:C:A}
					There is a context  $C''$ and there are graphs $K_1$, $\dots$, $K_{m-1}$, $L$, $K_{m+1}$, $\dots$, $K_n$ such that there are derivations
					\begin{equation*}
						\ods{C''\coons{\cneg{P}\connn{K_1, \dots,K_{m-1}, L , K_{m+1}, \dots, K_n}}{R''}}{\mathcal{D}_G'''}{	K_Y'\vlbin{\parr} G'}{\mathsf{GS}}
						\;,\;
						\ods{\varnothing}{\mathcal{D}'_m}{L \vlbin{\parr} M'}{\mathsf{GS}}
						\;,\;
						\ods{\varnothing}{\mathcal{D}_i}{K_i \vlbin{\parr} M_i}{\mathsf{GS}}
						\quad\mbox{and}\quad
						\ods{\varnothing}{\mathcal{D}_C''}{C''}{\mathsf{GS}}
                                                \hskip-4em
					\end{equation*}
					for $i \in \intset1n$ such that $i\neq m$.

					To conclude we let $C\coonso{R} = C'\coons{C''\coonso{R''}}{R'}$ 
					(see Lemma~\ref{lem:context}), 
					and $K_m= K_X'\vlbin{\parr}  L$ 
					Then let $\mathcal{D}_G$ 
					be defined as 
					\begin{equation*}
						\vlnostructuressyntax
						\small
						\odn{
							C'\Coons{
								\odn{
									C''\coons{\cneg{P}\connn{K_1, \hdots,
											K_{m-1}, K_X' \vlbin{\parr} L , K_{m+1}, \ldots, K_n}}{R''}
								}{\mathsf{s\mkern-1mu.\mkern-1mu sw}\mathord{\downarrow}}{
									K_X'
									\vlbin{\parr}
									\ods{
										C''\coons{\cneg{P}\connn{K_1, \hdots, K_{m-1},L , K_{m+1}, \ldots, K_n}}{R''}
									}{\mathcal{D}_G'''}{
										K_Y' \vlbin{\parr} G'
									}{}
									]
								}{}
							}{R'}
						}{\mathsf{s\mkern-1mu.\mkern-1mu sw}\mathord{\downarrow}}{
							\ods{
								C'\coons{
									K_X'\vlbin{\parr} K_Y'
								}{R'}
							}{\mathcal{D}_G''}{
								G''
							}{}
							\vlbin{\parr} G'
						}{}

					\end{equation*}
					and $\mathcal{D}_m$ be defined as
					\begin{equation*}
						\odn{
							\ods{\varnothing
							}{\mathcal{D}'_m}{
								[L ; M'\Coons{
									\ods{\varnothing}{\mathcal{D}'_X}{K_X' \vlbin{\parr} N_\ell}{}
								}{R_m}]
							}{}
						}{\mathsf{s\mkern-1mu.\mkern-1mu sw}\mathord{\downarrow}}{
							[K_X' ; L ; M'\coons{N_\ell}{R_m}]
						}{}
					\end{equation*}


					\item\label{split:b:II:C:B}
					there is a context  $C''\coonso{R''}$ and there are graphs $K_X $ and $K_Y''$ such that there are derivations
					\begin{equation*}
						\ods{C''\coons{K_X \vlbin{\parr} K_Y''}{R''}}{\mathcal{D}_G''' }{K_Y'\vlbin{\parr} G'}{\mathsf{GS}}
						\;,\;
						\ods{\varnothing}{\mathcal{D}_X}{K_X \vlbin{\parr} M_1}{\mathsf{GS}}
						\;,\;
						\ods{\varnothing}{\mathcal{D}''_Y}{K_Y'' \vlbin{\parr} P\connn{\varnothing,M_2,  \ldots, M_{m-1}, M', M_{m+1}, \ldots M_n }}{\mathsf{GS}}
						\quad\mbox{and}\quad
						\ods{\varnothing}{\mathcal{D}_C''}{C''}{\mathsf{GS}}
					\end{equation*}
					We conclude by setting $K_Y = K_X' \vlbin{\parr} K_Y''$  and $C\coonso{R} = C'\coons{C''\coonso{R''}}{R'}$, where
					the derivations $\mathcal{D}_G$ is defined as 
					\begin{equation*}

						\odn{
							C'\Coons{[K_X' ;
								\ods{[K_X ; K_Y'']}{\mathcal{D}_G'''}{[K_Y' ; G']}{}
								]}{R'}
						}{\mathsf{s\mkern-1mu.\mkern-1mu sw}\mathord{\downarrow}}{[
							\ods{C'\coons{[K_X'; K_Y']}{R'}}{\mathcal{D}_G''}{G''}{}
							; G'
							]}{}
					\end{equation*}
					and the derivation $\mathcal{D}_Y$ is defined as (recall that $M'\coons{N_\ell}{R_m}\isom M_m$):
					\begin{equation*}
						\vlnostructuressyntax
						\odn{
							\ods{\varnothing}{\mathcal{D}''_Y}{
								K_Y'' 
								\vlbin{\parr}  
								P\Connn{
									\varnothing, M_2\ldots, M_{m-1},
									M'\Coons{
										\ods{\varnothing}{\mathcal{D}_X'}{K_X' \vlbin{\parr} N_\ell}{}
									}{R_m},
									M_{m+1}, \ldots M_n 
								}
							}{}
						}{\mathsf{s\mkern-1mu.\mkern-1mu sw}\mathord{\downarrow}}{
							K_X' \vlbin{\parr}  K_Y'' \vlbin{\parr} P\connn{\varnothing, M_2, \ldots, M_{m-1},M'\Coons{N_\ell}{R_m}, M_{m+1}, 
								\ldots M_n }
						}{}
					\end{equation*}

					\item\label{split:b:II:C:C}
					there is a context  $C'$ and there are graphs $K_X'' $ and $ K_Y $ such that,  there are derivations 
					\begin{equation*}
                                          \scalebox{.9}{$
						\ods{C''\coons{K_X'' \vlbin{\parr} K_Y}{R''}}{\mathcal{D}_G'''}{K_Y'\vlbin{\parr} G'}{}
						\;,\;
						\ods{\varnothing}{\mathcal{D}_X''}{K_X''  \vlbin{\parr} M'}{\mathsf{GS}}
						\;,\;
						\ods{	\varnothing	}{\mathcal{D}_Y}{K_Y \vlbin{\parr} P\connn{M_1, M_2,\dots, M_{m-1}, \varnothing, M_{m+1}, \ldots M_n }}{\mathsf{GS}}
						\quad\mbox{and}\quad
						\ods{\varnothing}{\mathcal{D}_C''}{C''}{\mathsf{GS}}
                                                $}
                                          \hskip-4em
					\end{equation*}
					We conclude by letting $K_X = K_X' \vlbin{\parr} K_X''$  and $C\coonso{R} = C'\coons{C''\coonso{R''}}{R'}$, where the  derivations $\mathcal{D}_G$ and $\mathcal{D}_X$ are defined as follows
					\begin{equation*}
                                          \scalebox{.9}{$
						\odn{
							C'\Coons{
								\odn{C''\coons{K_X'\vlbin{\parr} K_X''\vlbin{\parr} K_Y}{R''}}
								{\mathsf{s\mkern-1mu.\mkern-1mu sw}\mathord{\downarrow}}
								{K_X'\vlbin{\parr} 
									\ods{C''\coons{K_X'' \vlbin{\parr} K_Y}{R'}}{\mathcal{D}_G'''}{K_Y'\vlbin{\parr} G'}{}}{}
							}{R''}
						}{\mathsf{s\mkern-1mu.\mkern-1mu sw}\mathord{\downarrow}}{
							\ods{
